INSERT INTO blog_post_translations
  (post_id, locale, slug, title, excerpt, body_html, seo_title, seo_description)
VALUES (
  :post_id, 'en', $x$fast-game-top-up$x$,
  $x$How to top up a game fast: from payment to credit$x$,
  $x$What makes a game top-up faster, where to see your order status, and what to do if the currency does not arrive right away.$x$,
$x$<h2>Key takeaways</h2>
<ul>
<li>A fast top-up starts with the right ID: a typo in the account number slows an order more than anything else.</li>
<li>On YuPay orders are processed automatically and usually credited within a few minutes, day or night.</li>
<li>The order page shows the status: Processing, Credited or Failed.</li>
<li>If the currency is late, do not pay a second time. Contact support with your order number.</li>
</ul>
<p>An in-game offer may last a few hours; a season pass is needed before the next match. So the time between paying and seeing the currency matters. Below: what depends on you, where to follow the order, and what to do if it is delayed.</p>
<h2>What makes a top-up faster</h2>
<p>Most time is lost to mistakes, not to payment. Three things to do before you press Pay:</p>
<ul>
<li><strong>Check the player ID.</strong> For many games, such as <a href="/en/store/mobile-legends">Mobile Legends</a>, the page has a Check button that shows the account nickname. If you see your nickname, the currency goes to you.</li>
<li><strong>Enter the server or region if the game asks for it.</strong> In Mobile Legends it is the second number next to the ID.</li>
<li><strong>Pick the payment method you have at hand.</strong> Click, Payme or Uzum: paying in soʻm takes a couple of taps in your bank app.</li>
</ul>
<p>The total in soʻm is shown before you pay, and exactly that is charged. No exchange rate to work out and no conversion to wait for, as there would be with a foreign card.</p>
<h2>How long the credit takes</h2>
<p>After payment the order goes into work on its own; no operator is needed. The currency usually arrives within a few minutes. Sometimes it takes longer: the game is updating its servers, or the bank takes longer to confirm the payment.</p>
<p>Topping up ahead of time is still wise. If an offer ends in the evening, place the order during the day, not five minutes before the end.</p>
<h2>How to follow the order status</h2>
<p>After payment you land on the order page. You can also find it under My orders. The statuses are:</p>
<ul>
<li><strong>Processing</strong> — payment received, the currency is being credited.</li>
<li><strong>Credited</strong> — the currency is on your account. Open the game and check.</li>
<li><strong>Failed</strong> — the order was not completed. Support will sort it out by the order number.</li>
</ul>
<p>Check the status right after paying, not an hour later. A wrong ID is easier to fix while the order is fresh.</p>
<h2>If the currency did not arrive</h2>
<p>Do not pay for the order again. A second payment does not speed up the first, and later there are two to untangle.</p>
<p>Go step by step:</p>
<ul>
<li>Open the order page and look at the status.</li>
<li>If it says Processing, wait 10–15 minutes.</li>
<li>If it says Credited, restart the game: sometimes the balance updates with a delay.</li>
<li>If it says Failed, or the order has been stuck for more than 15 minutes, contact support and include the order number.</li>
</ul>
<p>With the order number support sees the whole history at once and asks no extra questions.</p>
<h2>How to avoid a slow or unsafe seller</h2>
<p>Speed matters, but not at the cost of safety. A top-up by ID never needs your account password. If a seller asks for a login and password, walk away. More in our guide on <a href="/en/blog/buy-in-game-currency-safely">how to buy in-game currency safely</a>.</p>
<p>The second sign of a good service is a price without surprises at the last step. We covered where extra charges hide in the post on <a href="/en/blog/hidden-fees-game-top-ups">hidden fees in game top-ups</a>.</p>
<p>Pick a game in the <a href="/en/store">catalogue</a>, check your ID and top up ahead of time, before the offer starts.</p>$x$,
  $x$How to top up a game fast in Uzbekistan, paid in soʻm$x$,
  $x$Top up a game fast in Uzbekistan: check your player ID before paying, pay in soʻm with Click, Payme or Uzum, follow the order status, and what to do if it is delayed.$x$
);

INSERT INTO blog_post_faqs (id, post_id, locale, sort_order, question, answer) VALUES
(gen_random_uuid(), :post_id, 'en', 0, $x$How long does a game top-up take on YuPay?$x$,
 $x$Usually a few minutes after payment. Orders are processed automatically at any time of day. Sometimes the credit takes longer, for example while the game is updating its servers.$x$),
(gen_random_uuid(), :post_id, 'en', 1, $x$Where can I see the order status?$x$,
 $x$On the order page that opens after payment, or under My orders. The status reads Processing, Credited or Failed.$x$),
(gen_random_uuid(), :post_id, 'en', 2, $x$The money was charged but the currency did not arrive. What should I do?$x$,
 $x$Do not pay again. Check the order status and the player ID. If there is still no currency after 15 minutes, or the status is Failed, contact support and include the order number.$x$);

