INSERT INTO blog_post_translations
  (post_id, locale, slug, title, excerpt, body_html, seo_title, seo_description)
VALUES (
  :post_id, 'uz', $x$oyinni-tez-toldirish$x$,
  $x$Oʻyinni tez toʻldirish: toʻlovdan hisobga tushishgacha$x$,
  $x$Oʻyinni toʻldirishni nima tezlashtiradi, buyurtma holatini qayerda koʻrish mumkin va valyuta darhol tushmasa nima qilish kerak.$x$,
$x$<h2>Asosiysi</h2>
<ul>
<li>Tez toʻldirish toʻgʻri ID dan boshlanadi: akkaunt raqamidagi xato buyurtmani hammadan koʻp sekinlashtiradi.</li>
<li>YuPay da buyurtma avtomatik bajariladi va odatda bir necha daqiqada, kechayu kunduz hisobga tushadi.</li>
<li>Holat buyurtma sahifasida koʻrinadi: «Bajarilmoqda», «Hisobga olindi» yoki «Xatolik».</li>
<li>Valyuta kechiksa, qayta toʻlamang. Buyurtma raqami bilan qoʻllab-quvvatlash xizmatiga yozing.</li>
</ul>
<p>Oʻyindagi aksiya bir necha soat davom etishi mumkin, mavsumiy pass esa keyingi matchdan oldin kerak. Shuning uchun toʻlovdan valyuta hisobga tushguncha qancha vaqt oʻtishi muhim. Quyida — sizga nima bogʻliq, buyurtmani qayerda kuzatish va u kechiksa nima qilish haqida.</p>
<h2>Toʻldirishni nima tezlashtiradi</h2>
<p>Vaqtning koʻp qismi toʻlovga emas, xatolarga ketadi. «Toʻlash» tugmasini bosishdan oldin uch narsani qiling:</p>
<ul>
<li><strong>Oʻyinchi ID sini tekshiring.</strong> Koʻp oʻyinlarda, masalan, <a href="/uz/store/mobile-legends">Mobile Legends</a> sahifasida «Tekshirish» tugmasi bor: u akkaunt nikini koʻrsatadi. Oʻz nikingizni koʻrsangiz, valyuta sizga tushadi.</li>
<li><strong>Oʻyin soʻrasa, server yoki regionni kiriting.</strong> Mobile Legends da bu ID yonidagi ikkinchi raqam.</li>
<li><strong>Qoʻlingizdagi toʻlov usulini tanlang.</strong> Click, Payme yoki Uzum: soʻmda toʻlov bank ilovasida bir necha bosishda oʻtadi.</li>
</ul>
<p>Soʻmdagi yakuniy summa toʻlovdan oldin koʻrinadi va aynan shu summa yechiladi. Xorijiy kartadagidek kursni hisoblash va konvertatsiyani kutish shart emas.</p>
<h2>Hisobga tushishini qancha kutish kerak</h2>
<p>Toʻlovdan keyin buyurtma oʻzi ishga tushadi, operator kerak emas. Odatda valyuta bir necha daqiqada keladi. Baʼzan uzoqroq: oʻyin serverlarini yangilayotgan boʻladi yoki bank toʻlovni sekinroq tasdiqlaydi.</p>
<p>Baribir oldindan toʻldirgan maʼqul. Aksiya kechqurun tugasa, buyurtmani kunduzi bering, tugashiga besh daqiqa qolganda emas.</p>
<h2>Buyurtma holatini qanday kuzatish mumkin</h2>
<p>Toʻlovdan keyin buyurtma sahifasi ochiladi. Uni «Buyurtmalarim» boʻlimida ham topasiz. Holatlar:</p>
<ul>
<li><strong>Bajarilmoqda</strong> — toʻlov qabul qilindi, valyuta hisobga oʻtkazilmoqda.</li>
<li><strong>Hisobga olindi</strong> — valyuta akkauntingizda. Oʻyinga kirib tekshiring.</li>
<li><strong>Xatolik</strong> — buyurtma bajarilmadi. Qoʻllab-quvvatlash xizmati buyurtma raqami boʻyicha hal qiladi.</li>
</ul>
<p>Holatni bir soatdan keyin emas, toʻlovdan soʻng darhol tekshiring. ID dagi xatoni buyurtma yangi paytida tuzatish osonroq.</p>
<h2>Valyuta tushmasa</h2>
<p>Buyurtma uchun qayta toʻlamang. Ikkinchi toʻlov birinchisini tezlashtirmaydi, keyin esa ikkalasini ajratishga toʻgʻri keladi.</p>
<p>Tartib bilan harakat qiling:</p>
<ul>
<li>Buyurtma sahifasini oching va holatni koʻring.</li>
<li>Holat «Bajarilmoqda» boʻlsa, 10–15 daqiqa kuting.</li>
<li>Holat «Hisobga olindi» boʻlsa, oʻyinga qayta kiring: baʼzan balans kechroq yangilanadi.</li>
<li>Holat «Xatolik» boʻlsa yoki buyurtma 15 daqiqadan koʻp osilib qolsa, qoʻllab-quvvatlash xizmatiga buyurtma raqami bilan yozing.</li>
</ul>
<p>Buyurtma raqami boʻlsa, xizmat butun tarixni darhol koʻradi va ortiqcha savol bermaydi.</p>
<h2>Sekin yoki xavfli sotuvchidan qanday qochish mumkin</h2>
<p>Tezlik muhim, lekin xavfsizlik hisobiga emas. ID orqali toʻldirish uchun akkaunt paroli kerak emas. Sotuvchi login va parol soʻrasa, undan voz keching. Batafsil — <a href="/uz/blog/oyin-valyutasini-xavfsiz-sotib-olish">oʻyin valyutasini xavfsiz sotib olish</a> haqidagi maqolada.</p>
<p>Yaxshi xizmatning ikkinchi belgisi — oxirgi qadamda kutilmagan qoʻshimchalarsiz narx. Qoʻshimcha toʻlovlar qayerda yashirinishini <a href="/uz/blog/donatdagi-yashirin-komissiyalar">donatdagi yashirin komissiyalar</a> haqidagi maqolada yozganmiz.</p>
<p><a href="/uz/store">Katalogdan</a> oʻyinni tanlang, ID ni tekshiring va aksiya boshlanishidan oldin toʻldiring.</p>$x$,
  $x$Oʻyinni tez toʻldirish: soʻmda toʻlov va hisobga tushish$x$,
  $x$Oʻzbekistonda oʻyinni tez toʻldirish: toʻlovdan oldin ID tekshiruvi, Click, Payme yoki Uzum orqali soʻmda toʻlov, buyurtma holati va valyuta kechiksa nima qilish.$x$
);

